using AcxiomCrm.Data;using AcxiomCrm.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCrm.Controllers.Api;
[ApiController,Route("api/leads"),Authorize]public class LeadsApiController:ControllerBase{private readonly ApplicationDbContext _db;public LeadsApiController(ApplicationDbContext db)=>_db=db;[HttpGet]public async Task<IActionResult>Get()=>Ok(await _db.Leads.AsNoTracking().Select(x=>new{x.LeadId,x.LeadCode,x.LeadName,x.Email,x.Phone,x.CompanyName,x.Source,x.Status,x.Priority,x.ExpectedValue,x.AssignedTo}).ToListAsync());[HttpPost]public async Task<IActionResult>Post(Lead x){if(!ModelState.IsValid)return ValidationProblem(ModelState);x.LeadCode="LEAD-"+Guid.NewGuid().ToString("N")[..8].ToUpper();x.CreatedDate=DateTime.UtcNow;_db.Add(x);await _db.SaveChangesAsync();return Created($"/api/leads/{x.LeadId}",new{x.LeadId,x.LeadCode,x.LeadName,x.Status});}}
